46	#[test]
47	fn stream_rejects_integrity_mismatch_and_removes_tmp() {
48	    let dist = json!({ "integrity": sri_sha512(b"other-bytes") });
49	    let (result, dest, _tmp) = run_stream(b"actual-bytes", Some(&dist), None);
50	    let err = result.unwrap_err();
51	    assert!(err.to_string().contains("EINTEGRITY"), "got: {err}");
52	    assert!(!dest.exists(), "tmp file must be removed on integrity mismatch");
53	}
