122	#[test]
123	fn stream_rejects_invalid_base64() {
124	    let tmp = TempDir::new().unwrap();
125	    let dest = tmp.path().join("out.tgz");
126	    // Pick an SRI for some real bytes so the integrity branch
127	    // parses cleanly — we want the failure to surface from the
128	    // base64 decoder, not the integrity parser.
129	    let dist = json!({ "integrity": sri_sha512(b"anything") });
130	    let result = stream_decode_verify_and_write(
131	        "foo-1.0.0.tgz",
132	        "!!!not-valid-base64@@@",
133	        None,
134	        Some(&dist),
135	        &dest,
136	    );
137	    let msg = result.unwrap_err().to_string();
138	    assert!(msg.contains("EINTEGRITY") && msg.contains("base64"), "got: {msg}");
