158	fn extracts_and_strips_attachments() {
159	    let mut body = json!({
160	        "name": "foo",
161	        "_attachments": {
162	            "foo-1.0.0.tgz": {
163	                "content_type": "application/octet-stream",
164	                "data": "aGVsbG8=", // "hello"
165	                "length": 5,
166	            }
167	        }
168	    });
169	    let attachments = extract_attachments(&mut body).unwrap();
170	    assert_eq!(attachments.len(), 1);
171	    assert_eq!(attachments[0].filename, "foo-1.0.0.tgz");
172	    assert_eq!(attachments[0].data, "aGVsbG8=");
173	    assert_eq!(attachments[0].declared_length, Some(5));
174	    assert!(body.get("_attachments").is_none(), "_attachments should be stripped");
175	}
