/// hosted-version immutability described on [`merge_manifest`]. A
/// version listed in `hosted_versions` keeps its stored data verbatim
/// (only `deprecated` may change, see [`preserve_hosted_version`]);
/// every other version takes the incoming entry, overriding any
/// existing entry on key collision.
fn merge_versions(
    existing: Option<&Value>,
    incoming: &Value,
    hosted_versions: Option<&Map<String, Value>>,
) -> Value {
    let mut merged = match existing {
        Some(Value::Object(obj)) => obj.clone(),
        _ => Map::new(),
    };
    if let Some(incoming_obj) = incoming.as_object() {
        for (version, incoming_entry) in incoming_obj {
            match hosted_versions.and_then(|hosted| hosted.get(version)) {
                Some(hosted_entry) => {
                    merged.insert(version.clone(), preserve_hosted_version(hosted_entry, incoming_entry));
                }
                None => {
                    merged.insert(version.clone(), incoming_entry.clone());
                }
            }
